import csv, sqlite3
with open('csv/superhero.csv') as f:
    heroes = {}
    for r in csv.DictReader(f):
        h = r.get('height_cm', '')
        if h:
            heroes[r['id']] = int(h)
conn = sqlite3.connect('db/hero_power.db')
c = conn.cursor()
c.execute('SELECT hp.hero_id, s.superhero_name, s.height_cm FROM hero_power hp JOIN superhero s ON hp.hero_id = s.id WHERE hp.power_id = 18')
for r in c.fetchall():
    print(r)
conn.close()

